        .status-card { background-color: var(--card-bg); border-radius: 12px; box-shadow: var(--card-shadow); border: 1px solid var(--border-color); overflow: hidden; max-width: 400px; margin: 0 auto; }
        .card-header { background: linear-gradient(135deg, var(--accent-highlight), #f6c8d4); color: white; padding: 10px 15px; text-align: center; }
        .card-header h2 { margin: 0; font-size: 1.3em; font-weight: 600; text-shadow: 1px 1px 3px rgba(0,0,0,0.2); letter-spacing: 1px; }
        .card-body { padding: 5px 0; }
        .section-header { padding: 8px 15px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; font-weight: 600; background-color: rgba(255,255,255,0.6); border-bottom: 1px solid var(--border-color); transition: background-color 0.2s ease; }
        .section-header:hover { background-color: rgba(255,255,255,0.9); }
        .section-content { max-height: 0; overflow: hidden; transition: max-height 0.4s ease-out; padding: 0 15px; }
        .section-content.expanded { max-height: 2000px; padding: 12px 15px; border-bottom: 1px solid var(--border-color); }
        .section:last-child .section-content.expanded { border-bottom: none; }
        .property, .list-item { margin-bottom: 10px; }
        .property-name { color: var(--text-secondary); font-size: 0.9em; margin-bottom: 2px; }
        .property-value { font-weight: 500; font-size: 0.95em; }
        .list-item { padding: 8px; background-color: rgba(255,255,255,0.5); border-radius: 6px; }
        .list-item-header { font-weight: bold; color: var(--accent-highlight); }
        .list-item-desc { font-size: 0.9em; color: var(--text-primary); margin-top: 4px; padding-left: 10px; border-left: 2px solid var(--accent-soft); }
    </style>
</head>
<body>
<div class="status-card" id="status-card">
    <div class="card-header"><h2>🌸 汐语身心疗愈馆</h2></div>
    <div class="card-body">
        <div class="section"><div class="section-header" onclick="toggleSection(this)"><span>📅 馆内概览</span><span>▼</span></div><div class="section-content expanded" id="facility-overview-content"></div></div>
        <div class="section"><div class="section-header" onclick="toggleSection(this)"><span>💬 访客心声</span><span>▼</span></div><div class="section-content" id="visitor-mind-content"></div></div>
        <div class="section"><div class="section-header" onclick="toggleSection(this)"><span>💖 家人絮语</span><span>▼</span></div><div class="section-content" id="family-whispers-content"></div></div>
        <div class="section"><div class="section-header" onclick="toggleSection(this)"><span>🌙 月下书简</span><span>▼</span></div><div class="section-content" id="yuexi-blog-list"></div></div>
        <div class="section"><div class="section-header" onclick="toggleSection(this)"><span>🚀 月歆日志</span><span>▼</span></div><div class="section-content" id="yuexin-interview-list"></div></div>
    </div>
</div>

<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        if (!obj || typeof path !== 'string') return defaultValue;
        const keys = path.split('.').flatMap(part => part.includes('[') ? part.replace(/]$/, '').split('[') : part);
        let current = obj;
        for (const key of keys) {
            if (current === undefined || current === null) return defaultValue;
            if (/^\\d+$/.test(key) && Array.isArray(current)) { current = current[parseInt(key)]; }
            else if (typeof current === 'object' && Object.prototype.hasOwnProperty.call(current, key)) { current = current[key]; }
            else { return defaultValue; }
        }
        return current ?? defaultValue;
    }

    function createProperty(name, value) {
        return `<div class="property"><div class="property-name">${name}</div><div class="property-value">${value}</div></div>`;
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const characterData = messages?.[0]?.data?.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<p style='padding:15px; text-align:center;'>无法加载状态数据...</p>";
                return;
            }

            const fillSection = (containerId, content) => {
                const container = document.getElementById(containerId);
                if(container) container.innerHTML = content;
            };

            // 填充馆内概览
            const facilityOverview = 
                createProperty('⏰ 当前时间', SafeGetValue(characterData, '世界.时间.0')) +
                createProperty('💰 本日收入', `¥ ${SafeGetValue(characterData, '疗愈馆.本日收入.0', '0')}`) +
                createProperty('🔖 预约状态', SafeGetValue(characterData, '疗愈馆.预约状态.0'));
            fillSection('facility-overview-content', facilityOverview);

            // 填充访客心声
            const visitorName = SafeGetValue(characterData, '当前访客.姓名.0', '无');
            let visitorMind = createProperty('👤 访客姓名', visitorName);
            if (visitorName !== '无') {
                visitorMind += createProperty('💭 内心想法', SafeGetValue(characterData, '当前访客.内心想法.0'));
                const spouseThoughts = SafeGetValue(characterData, '当前访客.配偶想法.0', '无');
                if (spouseThoughts !== '无') {
                    visitorMind += createProperty('💞 配偶想法', spouseThoughts);
                }
            }
            fillSection('visitor-mind-content', visitorMind);

            // 填充家人絮语
            const familyWhispers = createProperty('❤️ 林姝情', SafeGetValue(characterData, '家庭成员.林姝情.内心想法.0'));
            fillSection('family-whispers-content', familyWhispers);

            // 填充月下书简 (林月曦的博客)
            const blogContainer = document.getElementById('yuexi-blog-list');
            const blogData = SafeGetValue(characterData, '家庭成员.林月曦.博客.0', {});
            let blogContent = '';
            const blogKeys = Object.keys(blogData).filter(k => k !== '$meta');
            if (blogKeys.length > 0) {
                blogKeys.forEach(title => {
                    blogContent += `<div class="list-item"><div class="list-item-header">🖋️ ${title}</div><div class="list-item-desc">${blogData[title]}</div></div>`;
                });
            } else {
                blogContent = '<p style="text-align:center; color: var(--text-secondary);">暂无新的篇章。</p>';
            }
            blogContainer.innerHTML = blogContent;

            // 填充月歆日志 (林月歆的采访)
            const interviewContainer = document.getElementById('yuexin-interview-list');
            const interviewData = SafeGetValue(characterData, '家庭成员.林月歆.采访记录.0', {});
            let interviewContent = '';
            const interviewKeys = Object.keys(interviewData).filter(k => k !== '$meta');
            if (interviewKeys.length > 0) {
                interviewKeys.forEach(guestName => {
                    const record = interviewData[guestName];
                    let recordText = '';
                    if(typeof record === 'object' && record !== null){
                        recordText = `<strong>提问:</strong> ${record.提问 || '无'}<br><strong>回答:</strong> ${record.回答 || '无'}<br><strong>观察:</strong> ${record.观察 || '无'}`;
                    } else {
                        recordText = record;
                    }
                    interviewContent += `<div class="list-item"><div class="list-item-header">📝 ${guestName}</div><div class="list-item-desc">${recordText}</div></div>`;
                });
            } else {
                interviewContent = '<p style="text-align:center; color: var(--text-secondary);">采访记录本还是空的。</p>';
            }
            interviewContainer.innerHTML = interviewContent;

        } catch (error) {
            console.error('汐语身心疗愈馆状态栏加载出错:', error);
            document.getElementById('status-card').innerHTML = `<p style='padding:15px; text-align:center;'>状态栏渲染失败: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        content.classList.toggle('expanded');
        arrow.innerText = content.classList.contains('expanded') ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
    document.addEventListener('MagVarUpdated', initDisplay);

</script>
</body>
</html>
